INSERT INTO fyi.stop
    (id, name, description, status, cap, price, coordinatex, coordinatey, proposed_by, created_at,
     approved_by, approved_at, is_fixed, municipality, province, source_url)
SELECT id::uuid, name, description, 'Accepted', cap, 0, longitude, latitude, @editor,
       CURRENT_TIMESTAMP AT TIME ZONE 'UTC', @editor, CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
       true, municipality, province, source_url
FROM places
ON CONFLICT (source_url) WHERE draft_itinerary_id IS NULL DO NOTHING;
